import{_ as o,a0 as l,w as d,s as p,I as t,x as n,a1 as i,A as e,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"無需 sudo 使用 Podman 在 Linux 上運行容器 | LCTT x X-CMD","titleTemplate":false,"description":"無需 sudo 使用 Podman 在 Linux 上運行容器 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"無需 sudo 使用 Podman 在 Linux 上運行容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"無需 sudo 使用 Podman 在 Linux 上運行容器 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220111 Run containers on Linux without sudo in Podman","title":"無需 sudo 使用 Podman 在 Linux 上運行容器","tag":"202201","desc":""},"relativePath":"202201/20220111 Run containers on Linux without sudo in Podman.md","filePath":"[post].md"}'),r={name:"202201/20220111 Run containers on Linux without sudo in Podman.md"};function h(m,s,g,k,b,x){const a=l("Link");return d(),p("div",null,[s[22]||(s[22]=t("h1",{id:"無需-sudo-使用-podman-在-linux-上運行容器",tabindex:"-1"},[n("無需 sudo 使用 Podman 在 Linux 上運行容器 "),t("a",{class:"header-anchor",href:"#無需-sudo-使用-podman-在-linux-上運行容器","aria-label":"Permalink to “無需 sudo 使用 Podman 在 Linux 上運行容器”"},"​")],-1)),s[23]||(s[23]=t("blockquote",null,[t("p",null,"配置你的系統使用無根容器。")],-1)),s[24]||(s[24]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/18/033424l111pvcc1iy0a1a1.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=n("容器是現代計算的一個重要組成部分，隨着圍繞容器的基礎設施的發展，新的和更好的工具開始浮出水面。過去，你只需用 ",-1)),i(a,{href:"https://opensource.com/article/18/11/behind-scenes-linux-containers"},{default:e(()=>[...s[0]||(s[0]=[n("LXC",-1)])]),_:1}),s[3]||(s[3]=n(" 就可以運行容器，然而隨着 Docker 得到了普及，它開始變得越來越複雜。最終，我們在 ",-1)),i(a,{href:"http://podman.io"},{default:e(()=>[...s[1]||(s[1]=[n("Podman",-1)])]),_:1}),s[4]||(s[4]=n(" 得到了我們所期望的容器管理系統：一個無守護進程的容器引擎，它使容器和吊艙易於構建、運行和管理。",-1))]),s[25]||(s[25]=t("p",null,[n("容器直接與 Linux 內核能力（如控制組和命名空間）交互，它們在這些命名空間中產生大量的新進程。簡而言之，運行一個容器實際上就是在 Linux 系統內部運行一個 Linux 系統。從操作系統的角度來看，它看起來非常像一種管理和特權活動。普通用户通常不能像容器那樣自由支配系統資源，所以默認情況下，運行 Podman 需要 root 或 "),t("code",null,"sudo"),n(" 權限。然而，這只是默認設置，而且這絕不是唯一可用的設置。本文演示瞭如何配置你的 Linux 系統，使普通用户可以在不使用 "),t("code",null,"sudo"),n(" 的情況下（“"),t("ruby",null,[n("無根"),t("rt",null,"rootless")]),n("”）運行 Podman。")],-1)),s[26]||(s[26]=t("h3",{id:"命名空間的用户-id",tabindex:"-1"},[n("命名空間的用户 ID "),t("a",{class:"header-anchor",href:"#命名空間的用户-id","aria-label":"Permalink to “命名空間的用户 ID”"},"​")],-1)),t("p",null,[i(a,{href:"https://opensource.com/article/19/10/namespaces-and-containers-linux"},{default:e(()=>[...s[5]||(s[5]=[n("內核命名空間",-1)])]),_:1}),s[6]||(s[6]=n(" 本質上是一種虛構的結構，可幫助 Linux 跟蹤哪些進程屬於同一類。這是 Linux 中的“隊列護欄”。一個隊列中的進程與另一個隊列中的進程之間實際上沒有區別，但可以將它們用“警戒線”彼此隔離。要聲明一組進程為“容器”，而另一組進程為你的操作系統，將它們分開是關鍵。",-1))]),s[27]||(s[27]=u(`<p>Linux 通過用户 ID（UID）和組 ID（GID）來跟蹤哪個用户或組擁有的進程。通常情況下，一個用户可以訪問一千個左右的從屬 UID，以分配給命名空間的子進程。由於 Podman 運行的是分配給啓動容器的用户的整個從屬操作系統，因此你需要的不僅僅是默認分配的從屬 UID 和從屬 GID。</p><p>你可以用 <code>usermod</code> 命令授予一個用户更多的從屬 UID 和從屬 GID。例如，要授予用户 <code>tux</code> 更多的從屬 UID 和從屬 GID，選擇一個還沒分配用户的適當的高 UID（如 200000），然後將其增加幾千：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod \\</span></span>
<span class="line"><span>    --add-subuids 200000-265536 \\</span></span>
<span class="line"><span>    --add-subgids 200000-265536 \\</span></span>
<span class="line"><span>    tux</span></span></code></pre></div><h3 id="命名空間訪問" tabindex="-1">命名空間訪問 <a class="header-anchor" href="#命名空間訪問" aria-label="Permalink to “命名空間訪問”">​</a></h3><p>對命名空間數量也有限制。這通常被設置得很高。你可以用 <code>systctl</code>，即內核參數工具來驗證用户的命名空間分配：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysctl --all --pattern user_namespaces</span></span>
<span class="line"><span>user.max_user_namespaces = 28633</span></span></code></pre></div><p>這是很充足的命名空間，而且可能是你的發行版默認設置的。如果你的發行版沒有這個屬性或者設置得很低，那麼你可以在文件 <code>/etc/sysctl.d/userns.conf</code> 中輸入這樣的文本來創建它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user.max_user_namespaces=28633</span></span></code></pre></div><p>加載該設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysctl -p /etc/sysctl.d/userns.conf</span></span></code></pre></div><h3 id="在沒有-root-權限的情況下運行一個容器" tabindex="-1">在沒有 root 權限的情況下運行一個容器 <a class="header-anchor" href="#在沒有-root-權限的情況下運行一個容器" aria-label="Permalink to “在沒有 root 權限的情況下運行一個容器”">​</a></h3><p>當你設置好你的配置，重啓你的計算機，以確保你的用户和內核參數的變化被加載和激活。</p><p>重啓後，試着運行一個容器鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it busybox echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span></code></pre></div><h3 id="容器像命令一樣" tabindex="-1">容器像命令一樣 <a class="header-anchor" href="#容器像命令一樣" aria-label="Permalink to “容器像命令一樣”">​</a></h3><p>如果你是第一次接觸容器，可能會覺得很神秘，但實際上，它們與你現有的 Linux 系統沒有什麼不同。它們實際上是在你的系統上運行的進程，沒有仿真環境或虛擬機的成本和障礙。容器和你的操作系統之間的區別只是內核命名空間，所以它們實際上只是帶有不同標籤的本地進程。Podman 使這一點比以往更加明顯，當你將 Podman 配置為無根命令，容器感覺更像命令而不是虛擬環境。Podman 使容器和吊艙變得簡單，所以請試一試。</p><hr>`,17)),t("p",null,[s[8]||(s[8]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/22/1/run-containers-without-sudo-podman"},{default:e(()=>[...s[7]||(s[7]=[n("https://opensource.com/article/22/1/run-containers-without-sudo-podman",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:e(()=>[...s[9]||(s[9]=[n("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=n(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[11]||(s[11]=[n("geekpi",-1)])]),_:1}),s[16]||(s[16]=n(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[n("Linux中國",-1)])]),_:1}),s[21]||(s[21]=n(" 榮譽推出",-1))])])}const P=o(r,[["render",h]]);export{c as __pageData,P as default};
